// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.escape;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class EscapeAnalysisDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeeCalculator calc = new FeeCalculator();

        // Warm up so the JIT compiles the hot method and applies escape analysis.
        long warm = 0;
        for (int i = 0; i < 100_000; i++) warm += calc.feeInPaise(1_000_00L);
        log.fine(() -> "warmup checksum = " + warm);

        // Measured hot loop: millions of calls, each creating a NON-ESCAPING Money.
        long start = System.nanoTime();
        long total = 0;
        for (int i = 0; i < 50_000_000; i++) {
            total += calc.feeInPaise(i); // Money wrapper inside never escapes → scalar-replaced
        }
        long ms = (System.nanoTime() - start) / 1_000_000;
        long t = total, elapsed = Math.max(1, ms);
        log.info(() -> "computed 50,000,000 fees in " + elapsed + " ms (checksum=" + t + ")");
        log.info(() -> "the per-call Money wrapper does NOT escape → JIT scalar-replaces it");
        log.info(() -> "the local StringBuilder does NOT escape → lock elision removes any sync");
    }
}

// ─── Would be in Money.java (SMALL wrapper; stays local → non-escaping) ───
class Money {
    private final long amountPaise; // integer paise avoids float; keeps it tiny
    private final String currency;
    Money(long amountPaise, String currency) { this.amountPaise = amountPaise; this.currency = currency; }
    long paise() { return amountPaise; }
    // Returns a primitive, not 'this' → does not leak the object out.
    long feePaise(double rate) { return Math.round(amountPaise * rate); }
}

// ─── Would be in FeeCalculator.java (hot method using local-only objects) ───
class FeeCalculator {
    long feeInPaise(long amountPaise) {
        // NON-ESCAPING object: created, used, discarded entirely within this method.
        Money money = new Money(amountPaise, "INR");
        long fee = money.feePaise(0.001); // 0.1% fee

        // Local StringBuilder that never escapes → candidate for lock elision.
        StringBuilder note = new StringBuilder();
        note.append("fee=").append(fee).append(money.paise());
        if (note.length() < 0) throw new IllegalStateException(); // never true; keeps it live

        return fee; // only a PRIMITIVE leaves the method; Money/StringBuilder do not
    }
}
